interface Vehiculo {
    void conducir();
}

class Coche implements Vehiculo {
    public void conducir() { System.out.println("Conduciendo coche"); }
}

class Moto implements Vehiculo {
    public void conducir() { System.out.println("Conduciendo moto"); }
}

class VehiculoFactory {
    public static Vehiculo crearVehiculo(String tipo) {
        if (tipo.equalsIgnoreCase("coche")) return new Coche();
        if (tipo.equalsIgnoreCase("moto")) return new Moto();
        throw new IllegalArgumentException("Tipo desconocido");
    }
}

public class Main {
    public static void main(String[] args) {
        Vehiculo v1 = VehiculoFactory.crearVehiculo("coche");
        Vehiculo v2 = VehiculoFactory.crearVehiculo("moto");
        v1.conducir();
        v2.conducir();
    }
}
